/// <summary>
/// PaffH 28.01.21
/// </summary>
/// <param name = "_NDXRole2PrivilegTable_3_DS">FormDataSource</param>
public void setDataSourceNDXRole2PrivilegeTable_3_DS(FormDataSource _NDXRole2PrivilegTable_3_DS)
{
    int i;
    Query q;
    QueryBuildDataSource qbds1;
    NDXRole2PrivilegeTable_3_DS = _NDXRole2PrivilegTable_3_DS;

    q = NDXRole2PrivilegeTable_3_DS.query();
    for (i = 1; i <= q.dataSourceCount(); i++)
    {
        qbds1 = q.dataSourceNo(i);
        if (qbds1.table() == tableNum(NDXSecurityFilterTable))
        {
            qbrNDXSecurityFilterTable_NDXPrivilegeTable_3_NDXSecurityFilterTableEnterprise = qbds1.addRange(fieldNum(NDXSecurityFilterTable, CountLicenseEnterprise));
            qbrNDXSecurityFilterTable_NDXPrivilegeTable_3_NDXSecurityFilterTableActivity = qbds1.addRange(fieldNum(NDXSecurityFilterTable,CountLicenseActivity));
            qbrNDXSecurityFilterTable_NDXPrivilegeTable_3_NDXSecurityFilterTableTeamMember = qbds1.addRange(fieldNum(NDXSecurityFilterTable,CountLicenseUniversal));
            break;
        }
    }
}

