/// <summary>
/// PaffH 27.01.21
/// filter: Enterprice-License
/// </summary>
/// <param name = "qValue">str</param>
public void setQueryValueForLicenseEnterprise(str qValue)
{
    if (qbrUserInfo_3_NDXSecurityFilterTableEnterprise)
    {
        qbrUserInfo_3_NDXSecurityFilterTableEnterprise.value(qValue);
    }
    if (qbrNDXRoleTable_NDXSecurityFilterTableEnterprise)
    {
        qbrNDXRoleTable_NDXSecurityFilterTableEnterprise.value(qValue);
    }
    if (qbrNDXSecurityFilterTable_NDXPrivilegeTable_NDXSecurityFilterTableEnterprise)
    {
        qbrNDXSecurityFilterTable_NDXPrivilegeTable_NDXSecurityFilterTableEnterprise.value(qValue);
    }
    if (qbrNDXSecurityFilterTable_NDXPrivilegeTable_3_NDXSecurityFilterTableEnterprise)
    {
        qbrNDXSecurityFilterTable_NDXPrivilegeTable_3_NDXSecurityFilterTableEnterprise.value(qValue);
    }
    if (qbrNDXSecurityFilterTable_NDXRoleTable_3_NDXSecurityFilterTableEnterprise)
    {
        qbrNDXSecurityFilterTable_NDXRoleTable_3_NDXSecurityFilterTableEnterprise.value(qValue);
    }

    if (qbrNDXSecurityRelatedObjectTable_ComputedLicenseType)
    {
        qbrNDXSecurityRelatedObjectTable_ComputedLicenseType.enabled(qValue != nullValueFromType(Types::String));
        qbrNDXSecurityRelatedObjectTable_ComputedLicenseType.value(queryValue(UserLicenseType::Enterprise));
    }
    if (qbrNDXSecurityRelatedObjectTable_3_ComputedLicenseType)
    {
        qbrNDXSecurityRelatedObjectTable_3_ComputedLicenseType.enabled(qValue != nullValueFromType(Types::String));
        qbrNDXSecurityRelatedObjectTable_3_ComputedLicenseType.value(queryValue(UserLicenseType::Enterprise));
    }
}

