/// <summary>
/// PaffH 27.01.21
/// executeQuery() after range change
/// </summary>
public void executeQueryLicense()
{
    if (UserInfo_3_DS)
    {
        UserInfo_3_DS.executeQuery();
    }
    if (NDXRoleTable_DS)
    {
        NDXRoleTable_DS.executeQuery();
    }
    if (NDXSecurityFilterTable_NDXPrivilegeTable_DS)
    {
        NDXSecurityFilterTable_NDXPrivilegeTable_DS.executeQuery();
    }            
    if (NDXSecurityRelatedObjectTable_DS)
    {
        NDXSecurityRelatedObjectTable_DS.executeQuery();
    }
    if (NDXSecurityRelatedObjectTable_3_DS)
    {
        NDXSecurityRelatedObjectTable_3_DS.executeQuery();
    }
    if (NDXRole2PrivilegeTable_3_DS)
    {
        NDXRole2PrivilegeTable_3_DS.executeQuery();
    }
    if (SecurityUserRole_3_DS)
    {
        SecurityUserRole_3_DS.executeQuery();
    }
}

/// <summary>
/// PaffH 27.01.21
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXPrivilegeManagementForm, FormRadioButtonNDXLicenseTypeFilter), FormControlEventType::SelectionChanged),
    SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void FormRadioButtonNDXLicenseTypeFilter_OnSelectionChanged(FormControl sender, FormControlEventArgs e)
{
    FormRadioControl formRadioControl = sender as formRadioControl;
    FormRun formRun = sender.formRun() as FormRun;
    NDXPrivilegeManagementFormHandler nDXPrivilegeManagementFormHandler = formRun.getPrivilegeManagementFormHandler();

    nDXPrivilegeManagementFormHandler.setQueryValueForLicenseEnterprise(SysQuery::valueUnlimited());
    nDXPrivilegeManagementFormHandler.setQueryValueForLicenseActivity(SysQuery::valueUnlimited());
    nDXPrivilegeManagementFormHandler.setQueryValueForLicenseTeamMember(SysQuery::valueUnlimited());
    NDXLicenseTypeFilter licenseTypeFilter = any2Enum(formRadioControl.selection());
    switch (licenseTypeFilter)
    {
        case NDXLicenseTypeFilter::withoutFilter :
            break;
        case NDXLicenseTypeFilter::Activity :
            nDXPrivilegeManagementFormHandler.setQueryValueForLicenseActivity(SysQuery::valueNotEmptyString());
            break;
        case NDXLicenseTypeFilter::Enterprise :
            nDXPrivilegeManagementFormHandler.setQueryValueForLicenseEnterprise(SysQuery::valueNotEmptyString());
            break;
        case NDXLicenseTypeFilter::TeamMember :
            nDXPrivilegeManagementFormHandler.setQueryValueForLicenseTeamMember(SysQuery::valueNotEmptyString());
            break;
    }
    nDXPrivilegeManagementFormHandler.executeQueryLicense();
}
